-- Subject value: the pilot's missions, hazard <= subject.clearance AND (no certification OR certification IN subject.certifications).
SELECT Id, SectorId, ClientId, KindId, Title, Brief, Hazard, Fee, Deadline, RequiredCertId, BookedByUserId, AssignedSquadronId, StatusId, Notes FROM Missions WHERE (`Missions`.`SectorId` = 'a1111111-1111-4111-8111-111111111111') AND ((`Missions`.`Hazard` <= (SELECT `ca1`.`Clearance` FROM `Pilots` `ca1` WHERE `ca1`.`UserId` = 'f0000000-0000-4000-8000-000000000004') AND (`Missions`.`RequiredCertId` IS NULL OR EXISTS (SELECT 1 FROM `PilotCertifications` `ca2` WHERE `ca2`.`UserId` = 'f0000000-0000-4000-8000-000000000004' AND `ca2`.`CertificationId` = `Missions`.`RequiredCertId`)))) ORDER BY `Deadline` ASC, `Id` ASC LIMIT 26
